import {createNarrator} from './companion-narrator.js';
import {installMayShow} from './companion-show.js';
import {installCompanionPlus} from './companion-plus.js';
import {QUOTES,MOODS,TRACKS,nextQuote,replyTo,restoreGarden,connectionText} from './companion-engine.js';
const $=s=>document.querySelector(s);
const KEY='hen-ngay-mai-cloud-v2';
let state=restoreGarden(null),saved=true;
try{state=restoreGarden(localStorage.getItem(KEY));}catch{saved=false;}
let lastQuote=-1,selectedMood=null,chat=[],intent='listen',currentDialog=null,playing=false,voiceState='idle',trackId='ordinary',reactTimer=null,popped=0,chatTimer=null;
let ambience=null,soundOn=false,plus=null,show=null;
const narrator=createNarrator({onState:updateVoice});
const prefersReduced=matchMedia('(prefers-reduced-motion: reduce)');
const safe=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={heart:'<path d="M12 20 3.8 12A5.2 5.2 0 0 1 12 5.8 5.2 5.2 0 0 1 20.2 12Z"/>',moon:'<path d="M20 14.3A8.5 8.5 0 0 1 9.7 4 8.5 8.5 0 1 0 20 14.3Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"/>',sound:'<path d="M3 9h4l5-4v14l-5-4H3ZM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/>',motion:'<path d="M9 5v14M15 5v14"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',bubble:'<circle cx="9" cy="14" r="7"/><circle cx="18" cy="6" r="3"/><path d="M5 12a4 4 0 0 1 3-2M17 17h.01"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12H2v7h5v-7ZM20 12h2v7h-5v-7Z"/>',leaf:'<path d="M20 3C8 1 1 9 7 18c10 4 16-4 13-15ZM4 22 17 7"/>',letter:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="m3 7 9 7 9-7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',play:'<path d="m8 4 12 8-12 8Z"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',copy:'<rect x="8" y="8" width="12" height="14" rx="2"/><path d="M15 8V3H3v14h5"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.heart}</svg>`;
const mascotSVG=`<svg class="may-svg" viewBox="0 0 300 320" aria-hidden="true"><defs><linearGradient id="body-shade" x1="0" y1="0" x2=".5" y2="1"><stop stop-color="#fffef7"/><stop offset="1" stop-color="#f2e8f2"/></linearGradient><radialGradient id="blush"><stop stop-color="#f6b1b7" stop-opacity=".8"/><stop offset="1" stop-color="#f6b1b7" stop-opacity="0"/></radialGradient></defs><g class="feet"><ellipse cx="112" cy="276" rx="26" ry="15" fill="#d3bdde"/><ellipse cx="189" cy="276" rx="26" ry="15" fill="#d3bdde"/></g><g class="arm arm-left"><path d="M72 178Q22 177 26 213q8 18 25-1l30-13" fill="#faf3ed" stroke="#d7bfcc" stroke-width="3"/></g><g class="arm arm-right"><path d="M225 178q48-9 47 28-8 22-29 3l-21-11" fill="#faf3ed" stroke="#d7bfcc" stroke-width="3"/></g><path class="cloud-body" d="M66 247C25 245 21 186 45 165 20 124 57 77 93 85 101 38 160 26 187 61 226 39 267 79 249 117 289 140 280 192 249 208 250 254 209 278 175 266 138 288 94 278 66 247Z" fill="url(#body-shade)" stroke="#cdb9d1" stroke-width="3.5"/><path d="M72 247q77 34 153-8" fill="none" stroke="#e1d0e2" stroke-width="6" stroke-linecap="round" opacity=".6"/><g class="sprout"><path d="M149 60q-2-18 10-27" fill="none" stroke="#789f76" stroke-width="4" stroke-linecap="round"/><path d="M157 40q-25 0-26-23 25-4 26 23Z" fill="#badb98" stroke="#8eb27e" stroke-width="2"/><path d="M157 38q-1-23 21-25 10 21-21 25Z" fill="#d5e9a9" stroke="#8eb27e" stroke-width="2"/></g><ellipse cx="83" cy="182" rx="30" ry="19" fill="url(#blush)"/><ellipse cx="219" cy="182" rx="30" ry="19" fill="url(#blush)"/><g class="eyes"><g class="eye"><ellipse cx="108" cy="158" rx="8" ry="11" fill="#5e536d"/><circle cx="110" cy="155" r="2.6" fill="#fffdf5"/></g><g class="eye"><ellipse cx="193" cy="158" rx="8" ry="11" fill="#5e536d"/><circle cx="195" cy="155" r="2.6" fill="#fffdf5"/></g></g><path class="mouth" d="M138 180q12 15 25 0" fill="none" stroke="#8a6c82" stroke-width="4" stroke-linecap="round"/><path class="happy-eyes" d="M99 158q9-12 18 0m67 0q9-12 18 0" fill="none" stroke="#6a5972" stroke-width="4" stroke-linecap="round"/><g class="belly"><path d="M133 218q15-10 30 0v25h-30Z" fill="#c7dcc0"/><path d="M148 243v-22m0 7-8-5m8 12 8-5" fill="none" stroke="#8eaf88" stroke-width="2" stroke-linecap="round"/></g></svg>`;
$('#mascot').innerHTML=mascotSVG;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{saved=false;}}
function apply(){
 document.body.dataset.mode=state.mode;
 document.body.classList.toggle('still',!state.motion||prefersReduced.matches);
 $('#mode').setAttribute('aria-pressed',state.mode==='night');
 $('#mode').setAttribute('aria-label',state.mode==='night'?'Chuyển về ban ngày':'Chuyển sang chế độ ngồi yên');
 $('#mode').innerHTML=icon(state.mode==='night'?'sun':'moon')+`<span>${state.mode==='night'?'Về ban ngày':'Ngồi yên'}</span>`;
 $('#motion').setAttribute('aria-pressed',!state.motion||prefersReduced.matches);
 $('#motion').setAttribute('aria-label',!state.motion?'Bật chuyển động':'Tạm dừng chuyển động');
 $('#garden-label').textContent=document.body.dataset.scene==='stage'?'SÂN KHẤU NHỎ CỦA MÂY':document.body.dataset.scene==='room'?'PHÒNG TRÀ CỦA MÂY':state.mode==='night'?'MỘT GÓC YÊN TĨNH CÙNG MÂY':'GÓC VƯỜN NHỎ CỦA BẠN';
 renderFlowers();
}
function say(text,emotion='happy'){$('#speech-text').textContent=text;react(emotion);}
function react(emotion='happy'){clearTimeout(reactTimer);$('#mascot').dataset.reaction=emotion;reactTimer=setTimeout(()=>{delete $('#mascot').dataset.reaction;},1800);}
function sparkle(x=50,y=57){if(!state.motion||prefersReduced.matches)return;for(let i=0;i<7;i++){const el=document.createElement('span');el.className='spark';el.textContent=['✦','♡','✧'][i%3];el.style.cssText=`left:${x}%;top:${y}%;--dx:${(i-3)*27}px;--dy:${-60-Math.abs(i-3)*10}px;--r:${i*35}deg`;$('#particles').append(el);setTimeout(()=>el.remove(),1500);}}
function quote(){lastQuote=nextQuote(lastQuote);say(QUOTES[lastQuote]);sparkle();}
function flowerSVG(i){return `<svg viewBox="0 0 60 80" aria-hidden="true"><path d="M30 76V35M30 62Q11 38 12 58q4 13 18 8M30 55q23-23 20-4-3 12-20 11" stroke="#78a17a" stroke-width="3" fill="#b8d49a"/><g fill="${['#f8c4cc','#d5c0ef','#ffe5a0'][i%3]}" stroke="${['#e5a9ba','#b7a0d2','#e6c77b'][i%3]}" stroke-width="1.5"><ellipse cx="30" cy="20" rx="9" ry="14"/><ellipse cx="16" cy="29" rx="13" ry="9" transform="rotate(30 16 29)"/><ellipse cx="21" cy="43" rx="9" ry="13" transform="rotate(30 21 43)"/><ellipse cx="41" cy="43" rx="9" ry="13" transform="rotate(-30 41 43)"/><ellipse cx="44" cy="28" rx="13" ry="9" transform="rotate(-30 44 28)"/></g><circle cx="30" cy="32" r="8" fill="#ffe5a0" stroke="#e2bf77" stroke-width="1.5"/></svg>`;}
function renderFlowers(){$('#flowers').innerHTML=Array.from({length:state.flowers},(_,i)=>`<span class="flower" style="--i:${i};--lift:${i%2}">${flowerSVG(i)}</span>`).join('');$('#flowers').setAttribute('aria-label',`${state.flowers} bông hoa trong vườn`);$('#plot small').textContent=state.seed?'Hạt đang chăm':'Gieo một việc nhỏ';$('#plot').setAttribute('aria-label',state.seed?'Xem việc nhỏ đã gieo':'Gieo một việc nhỏ cho mình');$('#garden').dataset.seed=!!state.seed;if(state.seed)$('#flowers').insertAdjacentHTML('beforeend','<span class="seedling" aria-hidden="true">🌱</span>');}
function plant(){plus.seeds();}
function renderMoods(){$('#moods').innerHTML=MOODS.map(m=>`<button class="mood ${m.id===selectedMood?'selected':''}" data-mood="${m.id}" aria-pressed="${m.id===selectedMood}"><span>${m.emoji}</span>${m.label}</button>`).join('');}
function popGame(){playing=!playing;$('#bubble-game').hidden=!playing;$('#play-button').setAttribute('aria-pressed',playing);$('#speech').hidden=playing;$('#tap-hint').hidden=playing;if(playing){popped=0;$('.play-caption>span').textContent='Chạm một bong bóng, để nó bay đi.';$('#bubbles').innerHTML=Array.from({length:6},(_,i)=>bubble(i)).join('');react('wave');}else $('#bubbles').innerHTML='';}
function bubble(i){return `<button class="bubble b${i}" data-bubble="${i}" aria-label="Chạm bong bóng ${i+1}" style="--delay:${-i*.8}s"><span aria-hidden="true">${['✧','♡','✿','✧','☁','♡'][i]}</span></button>`;}
function pop(el){if(el.classList.contains('popped'))return;el.classList.add('popped');el.disabled=true;popped++;react('happy');chime(1+popped%3);$('#status').textContent=`Đã chạm ${popped} bong bóng.`;if(popped===6){$('.play-caption>span').textContent='Xong rồi. Mình về vườn hay chơi thêm?';const again=document.createElement('button');again.className='play-again';again.textContent='Thêm một lượt';again.dataset.again='true';$('#bubbles').append(again);}}
let opener=null;
function open(kind,html){show?.stop();plus?.cleanup();document.body.dataset.urgent='false';stopVoice();clearTimeout(chatTimer);currentDialog=kind;if(!$('#dialog').open)opener=document.activeElement;$('#dialog-body').innerHTML=html;$('#dialog').dataset.kind=kind;if(!$('#dialog').open)$('#dialog').showModal();$('#close-dialog').focus();}
function close(){plus?.cleanup();stopVoice();clearTimeout(chatTimer);chat=[];document.body.dataset.urgent='false';$('#dialog').close();currentDialog=null;opener?.isConnected&&opener.focus();}
function chatView(){plus.chatView();}
function listen(deep=false){plus.setScene('room');if(deep){state.mode='night';persist();apply();trackId='ordinary';}open('listen',`<p class="eyebrow">MỘT CHÚT ÂM THANH, MỘT CHÚT KHOẢNG NGHỈ</p><h2 id="dialog-title">Nghe cùng Mây.</h2><p class="listen-subtitle">Bốn chuyện nhỏ, một chỗ ngồi dành cho bạn.</p><div class="track-list">${TRACKS.map(t=>`<button class="track ${t.id===trackId?'selected':''}" data-track="${t.id}" aria-pressed="${t.id===trackId}"><span class="track-emoji">${t.emoji}</span><span><small>${t.tag}</small><strong>${t.title}</strong></span><span class="track-arrow">↗</span></button>`).join('')}</div><span class="narration-badge" id="narration-badge">✦ Giọng Mây · AI tạo sẵn</span><section class="voice-player"><div class="vinyl" aria-hidden="true"><span>☁</span></div><div><strong id="now-title"></strong><p id="voice-status">Sẵn sàng khi bạn muốn.</p><span class="equalizer" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span></div><div class="voice-actions"><button id="voice-play" class="round-play" aria-label="Phát bài đọc">${icon('play')}</button><button id="voice-stop" class="round-stop" aria-label="Dừng bài đọc">${icon('stop')}</button></div></section><div class="narration-seek"><label class="sr-only" for="narration-seek">Tua câu chuyện</label><input id="narration-seek" type="range" min="0" max="0" value="0" step="0.1" disabled><div class="narration-time"><span id="narration-elapsed">0:00</span><span id="narration-duration">0:00</span></div></div><div class="voice-options"><label>Giọng kể <select id="voice-source"><option value="recorded">Mây · AI tạo sẵn</option><option value="device">Giọng thiết bị</option></select></label><label>Nhịp kể <select id="voice-speed"><option value="0.85">Chậm · 0.85×</option><option value="1" selected>Tự nhiên · 1×</option><option value="1.1">Nhanh hơn · 1.1×</option></select></label></div><label class="voice-volume">♫ Âm lượng <input id="voice-volume" type="range" min="0" max="1" step="0.05" value="0.85"></label><p class="narration-caption" id="narration-hint"></p><details class="transcript"><summary>Đọc bản chữ</summary><p id="transcript"></p></details><p class="privacy-note">Bản kể được tạo bằng AI từ chuyện viết riêng cho game, không mô phỏng giọng người thật. Lời tâm sự của bạn không được dùng để tạo âm thanh.</p><details class="podcast-sources"><summary>Chủ đề tham khảo từ Hêu Podcast ↗</summary><a href="https://www.youtube.com/watch?v=zDQ4f3gKqyQ" target="_blank" rel="noopener noreferrer">Sống một cuộc đời bình thường</a><a href="https://www.youtube.com/watch?v=Fe9mf1e88Uk" target="_blank" rel="noopener noreferrer">Ngày ta thôi tò mò về nỗi buồn của nhau</a><a href="https://www.youtube.com/watch?v=pczGiz9aQyM&amp;t=18s" target="_blank" rel="noopener noreferrer">Lớn lên và cô đơn</a><a href="https://www.youtube.com/watch?v=ACMo04I7uP4" target="_blank" rel="noopener noreferrer">Mình đã vượt qua mặc cảm về ngoại hình như thế nào?</a><p>Bốn chuyện trong game được viết mới theo các chủ đề chung. Không dùng bản thu, giọng người dẫn hoặc chép cốt truyện của video gốc.</p></details>`);narrator.bind();selectTrack(trackId);}
function selectTrack(id){const t=TRACKS.find(t=>t.id===id)||TRACKS[0];trackId=t.id;narrator.select(t);if(t.tone==='night'){state.mode='night';persist();apply();}document.querySelectorAll('[data-track]').forEach(el=>{const active=el.dataset.track===trackId;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',active);});$('#now-title').textContent=t.title;$('#transcript').textContent=t.text;updateVoice('idle');}
function updateVoice(status,message){voiceState=status;if(!$('#voice-status'))return;$('#voice-status').textContent=message||({idle:'Sẵn sàng khi bạn muốn.',waiting:'Đang mở giọng đọc…',playing:'Đang đọc · giọng của thiết bị',paused:'Đã tạm dừng',ended:'Câu chuyện đã khép lại.'}[status]||'Chưa phát được giọng đọc.');$('.voice-player').dataset.state=status;$('#voice-play').innerHTML=icon(['playing','waiting'].includes(status)?'motion':'play');$('#voice-play').setAttribute('aria-label',['playing','waiting'].includes(status)?'Tạm dừng bài đọc':status==='paused'?'Tiếp tục bài đọc':'Phát bài đọc');$('#voice-play').disabled=false;if(ambience)ambience.gain.gain.value=soundOn?(status==='playing'?.003:.009):0;}
function startVoice(){narrator.toggle();}
function stopVoice(){narrator.stop();}
function connect(kind='talk'){const urgent=kind==='urgent';open('connect',`<p class="eyebrow">MỘT MỐI NỐI NGOÀI KHU VƯỜN</p><h2 id="dialog-title">${urgent?'Nhờ một người ở cạnh.':'Một tin nhắn nhỏ.'}</h2><p>${urgent?'Nếu bạn đang có nguy cơ làm hại bản thân, hãy tìm một người thật hỗ trợ ngay và liên hệ dịch vụ cấp cứu tại nơi bạn sống.':'Bạn chọn người mình tin, sửa câu chữ rồi tự quyết định có gửi hay không.'}</p><label class="field-label" for="connection-message">Lời nhắn bạn có thể sửa</label><textarea id="connection-message" rows="5" maxlength="1000">${connectionText(kind)}</textarea><button id="copy-message" class="primary">${icon('copy')} Sao chép lời nhắn</button><p class="privacy-note" id="copy-status" role="status">Game không tự gửi tin nhắn hoặc chọn người nhận.</p><button class="text-link" data-close="true">Mình muốn quay về vườn</button>`);}
function about(){open('about',`<p class="eyebrow">VỀ GÓC VƯỜN NÀY</p><h2 id="dialog-title">Mây là một nhân vật ảo.</h2><p>Mây Ơi là bản trải nghiệm dành cho người trưởng thành: chơi nhẹ, nghe chuyện và mở một cách chia sẻ. Màu sắc hay nhân vật dễ thương chưa chứng minh tác dụng điều trị.</p><p>Phần tâm sự có chế độ AI khi máy chủ đã được cấu hình và bản viết sẵn để thử giao diện. Cả hai đều có thể hiểu sai hoặc bỏ sót. Game không chẩn đoán, thay chuyên gia, hoặc cung cấp dịch vụ khẩn cấp. Nếu khó khăn kéo dài hay ảnh hưởng sinh hoạt, hãy tìm hỗ trợ phù hợp từ người thật và người có chuyên môn.</p><h3>Dữ liệu ở đâu?</h3><p>Bản viết sẵn giữ đoạn chat trong bộ nhớ phiên. Chế độ AI chỉ gửi tối đa 12 tin gần nhất tới nhà cung cấp đã hiển thị sau khi bạn đồng ý; app không lưu nội dung chat, nhưng nhà cung cấp áp dụng chính sách riêng. Đóng cửa sổ xóa chat ở app, không thu hồi nội dung đã gửi. Game lưu hạt đang chọn, số hoa, chế độ sáng/tối và tùy chọn chuyển động trên trình duyệt. Không lưu cảm xúc bạn chọn. Bản kể AI là các tệp âm thanh tạo sẵn từ chuyện viết riêng; không gửi chat để đọc. Giọng thiết bị có thể dùng dịch vụ mạng tùy cấu hình.</p><h3>Điều Mây không đòi hỏi</h3><p>Không chuỗi ngày bắt buộc, không phạt khi rời game, không lời hứa độc quyền hoặc điểm số sức khỏe.</p><div class="about-sources"><a href="https://www.unicef.org/vietnam/mental-health" target="_blank" rel="noopener noreferrer">UNICEF · Sức khỏe tâm thần người trẻ ↗</a><a href="https://www.apa.org/topics/artificial-intelligence-machine-learning/health-advisory-chatbots-wellness-apps" target="_blank" rel="noopener noreferrer">APA · Lưu ý về chatbot và ứng dụng wellness ↗</a><a href="https://www.who.int/en/news-room/fact-sheets/detail/autism-spectrum-disorders" target="_blank" rel="noopener noreferrer">WHO · Hiểu đúng về tự kỷ ↗</a></div><p class="privacy-note">Bản mẫu chưa được chuyên gia phản biện hoặc nghiên cứu hiệu quả sức khỏe. Tranh nền tạo bằng ImageGen; nhân vật chuyển động được dựng bằng SVG gốc.</p>`);}
function ensureAudio(){if(ambience)return;const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),gain=ctx.createGain();gain.gain.value=0;gain.connect(ctx.destination);[174.61,220,261.63].forEach((f,i)=>{const o=ctx.createOscillator();o.type='sine';o.frequency.value=f;o.detune.value=i*2;o.connect(gain);o.start();});const noise=ctx.createBufferSource(),buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),channel=buffer.getChannelData(0);for(let i=0;i<channel.length;i++)channel[i]=(Math.random()*2-1)*.35;noise.buffer=buffer;noise.loop=true;const filter=ctx.createBiquadFilter(),rainGain=ctx.createGain();filter.type='lowpass';filter.frequency.value=1100;rainGain.gain.value=0;noise.connect(filter);filter.connect(rainGain);rainGain.connect(ctx.destination);noise.start();ambience={ctx,gain,rainGain};}
function toggleSound(){try{ensureAudio();if(!ambience){$('#status').textContent='Thiết bị chưa phát được âm nền.';return;}soundOn=!soundOn;ambience.ctx.resume();ambience.gain.gain.setTargetAtTime(soundOn?.009:0,ambience.ctx.currentTime,.15);mixRain();$('#sound').setAttribute('aria-pressed',soundOn);$('#sound').setAttribute('aria-label',soundOn?'Tắt âm nền':'Bật âm nền');}catch{$('#status').textContent='Âm nền chưa mở được; bạn vẫn có thể chơi.';}}
function mixRain(){if(ambience)ambience.gain.gain.setTargetAtTime(soundOn&&document.body.dataset.scene!=='stage'?(voiceState==='playing'?.003:.009):0,ambience.ctx.currentTime,.15);if(ambience?.rainGain)ambience.rainGain.gain.setTargetAtTime(soundOn&&document.body.dataset.scene==='room'?.06:0,ambience.ctx.currentTime,.6);}
document.addEventListener('may-scene',mixRain);
function chime(n=1){if(!soundOn||!ambience)return;const {ctx}=ambience,o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=440*n/1.5;g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.4);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.45);}
plus=installCompanionPlus({open,close,say,react,icon,mascotSVG,getState:()=>state,saveState:v=>{state=v;persist();apply();},sparkle,chime});
show=installMayShow({getState:()=>state,say,react});
document.addEventListener('may-scene',()=>{if(playing)popGame();mixRain();});
$('#mascot').addEventListener('click',()=>{quote();chime();});
$('#mascot').addEventListener('pointermove',e=>{if(!state.motion||prefersReduced.matches)return;const r=e.currentTarget.getBoundingClientRect();e.currentTarget.style.setProperty('--look-x',`${(e.clientX-r.left-r.width/2)/r.width*8}px`);e.currentTarget.style.setProperty('--look-y',`${(e.clientY-r.top-r.height/2)/r.height*5}px`);});
$('#mascot').addEventListener('pointerleave',()=>{$('#mascot').style.setProperty('--look-x','0px');$('#mascot').style.setProperty('--look-y','0px');});
$('#moods').addEventListener('click',e=>{const el=e.target.closest('[data-mood]');if(!el)return;selectedMood=el.dataset.mood;const m=MOODS.find(m=>m.id===selectedMood);renderMoods();say(m.line,m.id==='sunny'?'happy':'calm');});
$('#mode').addEventListener('click',()=>{state.mode=state.mode==='day'?'night':'day';persist();apply();say(state.mode==='night'?'Mình ngồi yên một lát. Bạn không cần nói gì ngay.':'Một chút nắng trở lại rồi.','calm');});
$('#motion').addEventListener('click',()=>{state.motion=!state.motion;persist();apply();if(!state.motion)show?.stop();$('#status').textContent=state.motion?'Đã bật chuyển động theo cài đặt thiết bị.':'Đã dừng chuyển động trang trí.';});
$('#sound').addEventListener('click',toggleSound);$('#about').addEventListener('click',about);$('#plot').addEventListener('click',plant);$('#quiet-listen').addEventListener('click',()=>listen(true));$('#close-dialog').addEventListener('click',close);$('#end-play').addEventListener('click',popGame);
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();close();});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
document.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]');if(a){const type=a.dataset.action;if(playing&&type!=='play')popGame();if(type==='chat')chatView();if(type==='play'){if(document.body.dataset.scene==='stage')plus.setScene('garden');popGame();}if(type==='listen')listen();if(type==='plant')plant();if(type==='connect')connect();}
 const b=e.target.closest('[data-bubble]');if(b)pop(b);
 if(e.target.closest('[data-again]')){playing=false;popGame();}
 const t=e.target.closest('[data-track]');if(t)selectTrack(t.dataset.track);
 const c=e.target.closest('[data-connect]');if(c)connect(c.dataset.connect);
 if(e.target.closest('[data-close]'))close();
 if(e.target.closest('#voice-play'))startVoice();
 if(e.target.closest('#voice-stop'))stopVoice();
 if(e.target.closest('#copy-message'))copyMessage();
});
async function copyMessage(){const text=$('#connection-message').value;try{await navigator.clipboard.writeText(text);$('#copy-status').textContent='Đã sao chép. Bạn tự chọn người nhận và gửi khi muốn.';}catch{$('#connection-message').focus();$('#connection-message').select();$('#copy-status').textContent='Hãy dùng Sao chép trên thiết bị để giữ lời nhắn này.';}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){narrator.pause();ambience?.ctx.suspend();}else if(soundOn)ambience?.ctx.resume();});
prefersReduced.addEventListener('change',apply);
renderMoods();apply();
